<?php require __DIR__.'/includes/auth.php';require_admin();require __DIR__.'/config/database.php';$message='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';$role=$_POST['role']??'staff';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<6)$error='Enter a name, valid email, and password with at least 6 characters.';else{try{$s=$pdo->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role]);$message='User created successfully.';}catch(PDOException $e){$error='This email address is already in use.';}}}$users=$pdo->query('SELECT id,name,email,role,created_at FROM users ORDER BY id')->fetchAll();?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SIMS | Users</title><link rel="stylesheet" href="assets/css/style.css"><style>.user-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:20px}.user-grid label{display:block;font-size:12px;font-weight:700;margin:14px 0}.user-grid input,.user-grid select{display:block;width:100%;border:1px solid #e8e8f0;border-radius:7px;padding:11px;margin-top:7px;font:inherit}.success{background:#dcfce7;color:#15803d;padding:10px;border-radius:7px;font-size:13px}@media(max-width:800px){.user-grid{grid-template-columns:1fr}}</style></head><body class="dashboard-page"><aside class="sidebar"><div class="logo"><span>✎</span><div><strong>SIMS</strong><small>Stationery Inventory</small></div></div><nav><a href="dashboard.php">▦ Dashboard</a><a href="inventory.php">▤ Inventory</a><a class="active" href="manage_users.php">♙ Users</a></nav><a class="logout" href="logout.php">⇥ Sign out</a></aside><main class="dashboard"><header><div><p class="eyebrow">ADMIN › USERS</p><h1>User Management</h1></div></header><?php if($message):?><p class="success"><?=htmlspecialchars($message)?></p><?php endif;?><?php if($error):?><p class="alert"><?=htmlspecialchars($error)?></p><?php endif;?><div class="user-grid"><form method="post" class="content-card"><h2>Add User</h2><label>Full name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="6" required></label><label>Role<select name="role"><option value="staff">Staff</option><option value="admin">Admin</option></select></label><button class="primary-btn">Create User</button></form><section class="content-card"><h2>System Users</h2><table><thead><tr><th>Name</th><th>Email</th><th>Role</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=htmlspecialchars($u['name'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><span class="badge <?=$u['role']==='admin'?'low':'good'?>"><?=htmlspecialchars($u['role'])?></span></td></tr><?php endforeach;?></tbody></table></section></div></main></body></html>
